import{_ as n,o as h,c as i,a2 as c}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Danh sách Đề xuất Mở rộng Cài đặt","description":"","frontmatter":{},"headers":[],"relativePath":"vi/98-扩展设定建议清单.md","filePath":"vi/98-扩展设定建议清单.md","lastUpdated":1789183869000}'),g={name:"vi/98-扩展设定建议清单.md"};function u(d,t,a,o,r,l){return h(),i("div",null,[...t[0]||(t[0]=[c('<h1 id="danh-sach-đe-xuat-mo-rong-cai-đat" tabindex="-1">Danh sách Đề xuất Mở rộng Cài đặt <a class="header-anchor" href="#danh-sach-đe-xuat-mo-rong-cai-đat" aria-label="Permalink to &quot;Danh sách Đề xuất Mở rộng Cài đặt&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Số tài liệu</td><td>98</td></tr><tr><td>Mô-đun</td><td>Phụ lục và Tài liệu Tham khảo</td></tr><tr><td>Từ khóa chính</td><td>mở rộng cài đặt, đề xuất sáng tạo, hướng cài đặt, sự cởi mở, lĩnh vực chưa phát triển</td></tr></tbody></table><h2 id="_1-mo-ta" tabindex="-1">1. Mô tả <a class="header-anchor" href="#_1-mo-ta" aria-label="Permalink to &quot;1. Mô tả&quot;">​</a></h2><p>Tài liệu này liệt kê các hướng và đề xuất có sẵn cho sáng tạo mở rộng trong hệ thống cài đặt Văn minh Cộng sinh Mỏ neo, nhằm mục đích cung cấp cảm hứng và hướng dẫn cho những người tạo cài đặt, giúp họ thực hiện mở rộng cài đặt có giá trị trong khuôn khổ hiện có. Danh sách này được phân loại theo mô-đun, và mỗi hướng mở rộng bao gồm mô tả hướng, giá trị mở rộng, mối quan hệ với cài đặt hiện có và đề xuất sáng tạo. Cần nhấn mạnh rằng danh sách này chỉ là tham khảo đề xuất; những người tạo có thể tự do sáng tạo với điều kiện tuân theo tính nhất quán của cài đặt, hoặc có thể phát triển các hướng hoàn toàn mới không được bao gồm trong danh sách này. Tất cả các cài đặt mở rộng phải vượt qua kiểm tra của Tài liệu 97 &quot;Bảng Tự kiểm tra Mâu thuẫn Cài đặt&quot; trước khi được chính thức đưa vào.</p><h2 id="_2-huong-mo-rong-the-gioi-quan-va-cai-đat-cot-loi" tabindex="-1">2. Hướng Mở rộng Thế giới quan và Cài đặt Cốt lõi <a class="header-anchor" href="#_2-huong-mo-rong-the-gioi-quan-va-cai-đat-cot-loi" aria-label="Permalink to &quot;2. Hướng Mở rộng Thế giới quan và Cài đặt Cốt lõi&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Số</th><th>Hướng Mở rộng</th><th>Giá trị Mở rộng</th><th>Cài đặt Liên quan</th><th>Đề xuất Sáng tạo</th></tr></thead><tbody><tr><td>E01</td><td>Sự tồn tại ngoài ranh giới vũ trụ</td><td>Khám phá xem có vũ trụ khác hoặc sự tồn tại chiều cao hơn ngoài mạng lưới quy luật của Hengyuanzhou hay không, cung cấp thế giới quan vũ trụ rộng lớn hơn cho cài đặt</td><td>Tài liệu 00, Tài liệu 28</td><td>Có thể cài đặt sự tồn tại của &quot;bức tường vũ trụ&quot; và câu chuyện của vài nhà thám hiểm đã phá vỡ bức tường vũ trụ, để lại manh mối cho tương tác giữa các vũ trụ trong tương lai</td></tr><tr><td>E02</td><td>Bản chất ý chí vũ trụ</td><td>Thảo luận sâu sắc về việc liệu có &quot;ý chí vũ trụ&quot; nào ở tầng dưới của mạng lưới quy luật hay không và mối quan hệ của nó với cơ chế mỏ neo</td><td>Tài liệu 00, Tài liệu 20</td><td>Có thể cài đặt ý chí vũ trụ như một hiện tượng tự tổ chức quy luật không nhân cách hóa, thay vì một vị thần cụ thể, duy trì lập trường &quot;dựa trên thực tế&quot;</td></tr><tr><td>E03</td><td>Các nền văn minh bị mất của thời đại tiền mỏ neo</td><td>Cài đặt chi tiết các nền văn minh từng thịnh vượng nhưng đã biến mất trong thời đại tiền mỏ neo, làm phong phú chiều sâu lịch sử</td><td>Tài liệu 71, Tài liệu 93</td><td>Có thể cài đặt 3-5 nền văn minh bị mất đại diện, mỗi nền văn minh có hệ thống tu luyện, văn hóa và lý do biến mất độc đáo, cung cấp vật liệu cho cài đặt khảo cổ</td></tr><tr><td>E04</td><td>Các trường phái triết học của khái niệm cộng sinh</td><td>Dưới khuôn khổ lớn &quot;chống cướp bóc, ủng hộ cộng sinh&quot;, cài đặt các diễn giải khác nhau của các trường phái triết học khác nhau đối với khái niệm cộng sinh</td><td>Tài liệu 04, Tài liệu 03</td><td>Có thể cài đặt các trường phái như &quot;trường phái cộng sinh cấp tiến&quot;, &quot;trường phái cộng sinh ôn hòa&quot;, &quot;trường phái cộng sinh sinh thái&quot;, &quot;trường phái cộng sinh công nghệ&quot;, và sự đối đầu tư tưởng giữa chúng có thể trở thành sức căng thẳng cốt truyện quan trọng</td></tr></tbody></table><h2 id="_3-huong-mo-rong-he-thong-tu-luyen" tabindex="-1">3. Hướng Mở rộng Hệ thống Tu luyện <a class="header-anchor" href="#_3-huong-mo-rong-he-thong-tu-luyen" aria-label="Permalink to &quot;3. Hướng Mở rộng Hệ thống Tu luyện&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Số</th><th>Hướng Mở rộng</th><th>Giá trị Mở rộng</th><th>Cài đặt Liên quan</th><th>Đề xuất Sáng tạo</th></tr></thead><tbody><tr><td>E05</td><td>Phương pháp chi tiết của một hệ thống đơn lẻ</td><td>Mở rộng chi tiết một trong ba trăm hệ thống, bao gồm phương pháp tu luyện cụ thể, phương pháp đột phá cảnh giới, những sai lầm phổ biến, v.v.</td><td>Tài liệu 10-19, Tài liệu 91</td><td>Khuyến nghị ưu tiên mở rộng ba nền tảng gốc và các hệ thống trong hạng mục kỹ thuật ứng dụng gắn liền với công nghệ; tài liệu chi tiết của mỗi hệ thống có thể bao gồm các bước tu luyện, công thức tâm linh, nhu cầu tài nguyên, cảnh báo rủi ro, v.v.</td></tr><tr><td>E06</td><td>Kế hoạch kết hợp tu luyện đồng thời các hệ thống</td><td>Nghiên cứu khả năng tương thích của tu luyện đồng thời giữa các hệ thống khác nhau và thiết kế kế hoạch kết hợp đa hệ thống tối ưu</td><td>Tài liệu 10, Tài liệu 11-13</td><td>Có thể cài đặt &quot;kết hợp vàng&quot; (như lặp lại suy luận + quy luật không gian + kỹ thuật ứng dụng) và các kết hợp khác thường, phân tích ưu điểm và hạn chế của mỗi kết hợp</td></tr><tr><td>E07</td><td>Các nút thắt tu luyện và phương pháp đột phá</td><td>Cài đặt chi tiết các nút thắt mà mỗi hệ thống có thể gặp phải ở các cảnh giới khác nhau và nhiều phương pháp đột phá nút thắt</td><td>Tài liệu 14, Tài liệu 19</td><td>Có thể cài đặt các loại nút thắt khác nhau như &quot;kiệt nạn tâm ma&quot;, &quot;rào cản quy luật&quot;, &quot;chướng ngại gốc&quot;, và các con đường đột phá tương ứng, tăng cấp bậc của quá trình tu luyện</td></tr><tr><td>E08</td><td>Thể chất đặc biệt và sự thích ứng của hệ thống</td><td>Cài đặt các thể chất đặc biệt khác nhau (như thể đạo bẩm sinh, thân thể thân thiện nguyên tố, thân thể nhạy cảm ý thức, v.v.) và mối quan hệ thích ứng của chúng với các hệ thống tu luyện khác nhau</td><td>Tài liệu 12, Tài liệu 51</td><td>Có thể thiết kế một &quot;ma trận thích ứng thể chất-hệ thống&quot; để giúp những người tạo nhanh chóng đánh giá hệ thống nào phù hợp với một thể chất nhất định</td></tr><tr><td>E09</td><td>Phân loại chi tiết tài nguyên tu luyện</td><td>Phân loại và cài đặt chi tiết các tài nguyên khác nhau cần thiết cho tu luyện (báu vật thiên nhiên, tinh thể năng lượng, mảnh vỡ quy luật, v.v.)</td><td>Tài liệu 18, Tài liệu 65</td><td>Có thể cài đặt cấp độ, nơi sản xuất, phương pháp thu thập, phương pháp bảo quản, điều cấm sử dụng của tài nguyên, v.v., xây dựng hệ sinh thái tài nguyên tu luyện hoàn chỉnh</td></tr></tbody></table><h2 id="_4-huong-mo-rong-he-thong-xa-hoi" tabindex="-1">4. Hướng Mở rộng Hệ thống Xã hội <a class="header-anchor" href="#_4-huong-mo-rong-he-thong-xa-hoi" aria-label="Permalink to &quot;4. Hướng Mở rộng Hệ thống Xã hội&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Số</th><th>Hướng Mở rộng</th><th>Giá trị Mở rộng</th><th>Cài đặt Liên quan</th><th>Đề xuất Sáng tạo</th></tr></thead><tbody><tr><td>E10</td><td>Các hình thái xã hội cụ thể của năm loại phân loại</td><td>Mở rộng chi tiết hệ thống xã hội cụ thể, mô hình kinh tế và đặc điểm văn hóa của từng loại trong năm loại phân loại văn minh cộng sinh</td><td>Tài liệu 30-35</td><td>Mỗi loại có thể cài đặt hình thái thành phố điển hình, cấu trúc gia đình, mô hình giáo dục, lễ hội kỷ niệm, v.v., làm cho năm loại phân loại各具特色</td></tr><tr><td>E11</td><td>Quy hoạch và xây dựng thành phố cộng sinh</td><td>Cài đặt khái niệm quy hoạch, phong cách kiến trúc, cơ sở hạ tầng và phân khu chức năng của các thành phố trong văn minh cộng sinh</td><td>Tài liệu 39, Tài liệu 60</td><td>Có thể thiết kế các loại hình thái thành phố khác nhau như &quot;thành phố cộng sinh thẳng đứng&quot;, &quot;thành phố lồng ghép sinh thái&quot;, &quot;thành phố gấp không gian&quot;</td></tr><tr><td>E12</td><td>Vận hành chi tiết của hệ thống giáo dục</td><td>Cài đặt chi tiết cơ chế vận hành hoàn chỉnh của hệ thống giáo dục cộng sinh, từ giáo dục mầm non đến giáo dục đại học và giáo dục tu luyện</td><td>Tài liệu 37, Tài liệu 43</td><td>Có thể cài đặt hệ thống chương trình học, phương pháp đánh giá, hệ thống cố vấn, kế hoạch giáo dục liên chủng tộc, v.v.</td></tr><tr><td>E13</td><td>Vận hành chi tiết của hệ thống y tế</td><td>Cài đặt chi tiết cơ chế vận hành của hệ thống y tế cộng sinh, bao gồm sự kết hợp giữa y tế thông thường và y tế tu luyện</td><td>Tài liệu 38, Tài liệu 44</td><td>Có thể cài đặt hệ thống bệnh viện, quy trình hoàn trả bảo hiểm y tế, quy phạm đặc biệt của điều trị tu luyện, kế hoạch y tế liên chủng tộc, v.v.</td></tr><tr><td>E14</td><td>An sinh xã hội và hệ thống phúc lợi</td><td>Cài đặt chi tiết hệ thống an sinh xã hội của văn minh cộng sinh, bao gồm lão dưỡng, thất nghiệp, cứu trợ, v.v.</td><td>Tài liệu 32, Tài liệu 08</td><td>Có thể cài đặt điều kiện nhận phúc lợi, tiêu chuẩn phân phối, nguồn vốn, cơ chế giám sát, v.v.</td></tr></tbody></table><h2 id="_5-huong-mo-rong-phap-luat-va-quan-tri" tabindex="-1">5. Hướng Mở rộng Pháp luật và Quản trị <a class="header-anchor" href="#_5-huong-mo-rong-phap-luat-va-quan-tri" aria-label="Permalink to &quot;5. Hướng Mở rộng Pháp luật và Quản trị&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Số</th><th>Hướng Mở rộng</th><th>Giá trị Mở rộng</th><th>Cài đặt Liên quan</th><th>Đề xuất Sáng tạo</th></tr></thead><tbody><tr><td>E15</td><td>Các vụ án pháp luật điển hình</td><td>Viết các vụ án điển hình được Tòa án Cộng sinh xét xử, thể hiện việc áp dụng pháp luật trong thực tế</td><td>Tài liệu 40-49, Tài liệu 92</td><td>Có thể viết các vụ án đại diện như &quot;vụ án độc quyền tài nguyên tu luyện&quot;, &quot;vụ án bồi thường ô nhiễm liên mặt phẳng&quot;, &quot;vụ án quyền cơ thể thay thế bóng tối&quot;</td></tr><tr><td>E16</td><td>Hệ thống tự trị địa phương</td><td>Cài đặt chi tiết hệ thống tự trị và phân chia thẩm quyền của mỗi vùng sao, mỗi mặt phẳng trong khuôn khổ hiến pháp</td><td>Tài liệu 40, Tài liệu 49</td><td>Có thể cài đặt mô hình tự trị của các đơn vị tự trị khác nhau, mối quan hệ với chính phủ trung ương, quy trình xây dựng quy định tự trị, v.v.</td></tr><tr><td>E17</td><td>Hệ thống bầu cử và dân chủ</td><td>Cài đặt chi tiết hệ thống bầu cử đại biểu Hội đồng Mỏ neo và cơ chế ra quyết định dân chủ</td><td>Tài liệu 32, Tài liệu 49</td><td>Có thể cài đặt phân chia khu vực bầu cử, tư cách ứng cử viên, quy trình bầu cử, phương pháp bỏ phiếu, hệ thống nhiệm kỳ, v.v.</td></tr><tr><td>E18</td><td>Cơ chế thi hành pháp luật</td><td>Cài đặt chi tiết cơ chế thi hành pháp luật, bao gồm cơ quan thi hành, quy trình thi hành, biện pháp cưỡng chế</td><td>Tài liệu 48, Tài liệu 49</td><td>Có thể cài đặt cấu trúc tổ chức của cơ quan thi hành, thẩm quyền thi hành, quy trình thi hành, cơ chế giám sát, v.v.</td></tr></tbody></table><h2 id="_6-huong-mo-rong-su-song-va-chung-toc" tabindex="-1">6. Hướng Mở rộng Sự sống và Chủng tộc <a class="header-anchor" href="#_6-huong-mo-rong-su-song-va-chung-toc" aria-label="Permalink to &quot;6. Hướng Mở rộng Sự sống và Chủng tộc&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Số</th><th>Hướng Mở rộng</th><th>Giá trị Mở rộng</th><th>Cài đặt Liên quan</th><th>Đề xuất Sáng tạo</th></tr></thead><tbody><tr><td>E19</td><td>Cài đặt chi tiết của một chủng tộc đơn lẻ</td><td>Mở rộng chi tiết một chủng tộc trong Danh mục Tất cả các Chủng tộc, bao gồm đặc điểm sinh lý, cấu trúc xã hội, truyền thống văn hóa, tiến hóa lịch sử</td><td>Tài liệu 50-52, Tài liệu 94</td><td>Khuyến nghị ưu tiên mở rộng các chủng tộc đặc trưng như chủng tộc rồng, chủng tộc tiên, chủng tộc cơ khí, chủng tộc thực thể ý thức; mỗi chủng tộc có thể bao gồm ngôn ngữ, tôn giáo, nghệ thuật, phong tục, v.v.</td></tr><tr><td>E20</td><td>Các trường hợp cụ thể của sự sống kỳ lạ</td><td>Cài đặt các cá thể hoặc nhóm sự sống kỳ lạ cụ thể, thể hiện việc áp dụng thực tế của ba loại quy trình xử lý</td><td>Tài liệu 53-54</td><td>Có thể cài đặt các trường hợp sự sống kỳ lạ như &quot;người trôi dạt không gian&quot;, &quot;sự sống mảnh vỡ thời gian&quot;, &quot;thực thể ký sinh quy luật&quot;</td></tr><tr><td>E21</td><td>Các loại cụ thể của năng lượng kỳ lạ</td><td>Cài đặt chi tiết đặc điểm, nguồn gốc, công dụng và phương pháp quản lý của các năng lượng kỳ lạ khác nhau</td><td>Tài liệu 55-56</td><td>Có thể cài đặt các loại năng lượng kỳ lạ như &quot;năng lượng nhân quả&quot;, &quot;năng lượng ý thức&quot;, &quot;năng lượng vang vọng thời gian&quot;</td></tr><tr><td>E22</td><td>Các trường hợp cụ thể của cơ thể thay thế bóng tối</td><td>Cài đặt câu chuyện cá thể cụ thể của cơ thể thay thế bóng tối, thể hiện việc áp dụng thực tế của đạo đức linh hồn kép và bốn loại xử lý nhánh</td><td>Tài liệu 57-59</td><td>Có thể viết câu chuyện trường hợp của các loại cơ thể thay thế bóng tối khác nhau, khám phá tình thế tiến thoái lưỡng nan về đạo đức của sự cộng sinh linh hồn kép</td></tr><tr><td>E23</td><td>Con cháu của sự hòa hợp liên chủng tộc</td><td>Cài đặt đặc điểm và văn hóa của các chủng tộc hỗn hợp do hôn nhân giữa các chủng tộc khác nhau sinh ra</td><td>Tài liệu 52, Tài liệu 77</td><td>Có thể cài đặt các chủng tộc hỗn hợp như &quot;bán tiên&quot;, &quot;người rồng&quot;, &quot;người sinh học cơ khí&quot;, khám phá bản sắc và hòa hợp văn hóa của họ</td></tr></tbody></table><h2 id="_7-huong-mo-rong-cong-nghe-va-nang-luong" tabindex="-1">7. Hướng Mở rộng Công nghệ và Năng lượng <a class="header-anchor" href="#_7-huong-mo-rong-cong-nghe-va-nang-luong" aria-label="Permalink to &quot;7. Hướng Mở rộng Công nghệ và Năng lượng&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Số</th><th>Hướng Mở rộng</th><th>Giá trị Mở rộng</th><th>Cài đặt Liên quan</th><th>Đề xuất Sáng tạo</th></tr></thead><tbody><tr><td>E24</td><td>Nguyên lý chi tiết của một công nghệ đơn lẻ</td><td>Phân tích chi tiết nguyên lý của một công nghệ then chốt (như gương sao chép, không gian cách ly, kỹ thuật hóa quả Bei Zeng)</td><td>Tài liệu 60-69, Tài liệu 63-64</td><td>Có thể cài đặt lịch sử phát triển của công nghệ, thành phần cốt lõi, quy trình làm việc, hạn chế công nghệ, hướng nâng cấp, v.v.</td></tr><tr><td>E25</td><td>Phân loại chi tiết của dụng cụ tu luyện</td><td>Cài đặt phân loại, chức năng, cấp độ và phương pháp sử dụng của các dụng cụ hỗ trợ tu luyện khác nhau</td><td>Tài liệu 61, Tài liệu 67</td><td>Có thể cài đặt các loại dụng cụ như &quot;buồng tu luyện&quot;, &quot;máy dò quy luật&quot;, &quot;bộ chuyển đổi năng lượng&quot;, &quot;bộ khuếch đại ý thức&quot;</td></tr><tr><td>E26</td><td>Cài đặt chi tiết của phần cứng mỏ neo</td><td>Cài đặt chi tiết cấu trúc, chức năng, xây dựng và bảo trì của cơ sở hạ tầng phần cứng mỏ neo</td><td>Tài liệu 20, Tài liệu 67</td><td>Có thể cài đặt thành phần cốt lõi của mỏ neo nhân tạo, cung cấp năng lượng, chu kỳ bảo trì, xử lý sự cố, v.v.</td></tr><tr><td>E27</td><td>Công nghệ truyền thông liên mặt phẳng</td><td>Cài đặt chi tiết nguyên lý công nghệ, loại thiết bị, giao thức truyền thông và cơ chế an ninh của truyền thông liên mặt phẳng</td><td>Tài liệu 66, Tài liệu 81</td><td>Có thể cài đặt các phương thức truyền thông khác nhau như &quot;truyền thông sóng mỏ neo&quot;, &quot;truyền thông gấp không gian&quot;, &quot;truyền thông cộng hưởng ý thức&quot;</td></tr></tbody></table><h2 id="_8-huong-mo-rong-lich-su-va-su-kien" tabindex="-1">8. Hướng Mở rộng Lịch sử và Sự kiện <a class="header-anchor" href="#_8-huong-mo-rong-lich-su-va-su-kien" aria-label="Permalink to &quot;8. Hướng Mở rộng Lịch sử và Sự kiện&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Số</th><th>Hướng Mở rộng</th><th>Giá trị Mở rộng</th><th>Cài đặt Liên quan</th><th>Đề xuất Sáng tạo</th></tr></thead><tbody><tr><td>E28</td><td>Tường thuật chi tiết về sự kiện lịch sử quan trọng</td><td>Tường thuật lịch sử chi tiết về một sự kiện quan trọng trong biên niên sử</td><td>Tài liệu 70-79, Tài liệu 93</td><td>Có thể tường thuật chi tiết toàn bộ quá trình của các sự kiện như &quot;sự kiện mở cửa ba trăm hệ thống&quot;, &quot;thực hiện chiến lược kích hoạt 20%&quot;, &quot;cột mốc nâng chiều đầu tiên&quot;</td></tr><tr><td>E29</td><td>Tiểu sử của nhân vật lịch sử</td><td>Viết tiểu sử chi tiết cho các nhân vật then chốt, làm phong phú chiều sâu nhân văn của lịch sử</td><td>Tài liệu 95</td><td>Có thể viết tiểu sử cho các nhân vật then chốt như &quot;Tuyên Hằng Tử&quot;, &quot;Cộng Sinh Tử&quot;, &quot;Lập Hiến Công&quot;, &quot;Tam Bách Sư&quot;</td></tr><tr><td>E30</td><td>Phân tích giả định về điểm ngoặt lịch sử</td><td>Phân tích nếu một sự kiện lịch sử đi theo hướng khác, sự phát triển của văn minh cộng sinh sẽ khác nhau như thế nào</td><td>Tài liệu 70-79</td><td>Có thể thực hiện phân tích giả định như &quot;nếu hiến pháp cộng sinh không được thông qua&quot;, &quot;nếu chiến lược kích hoạt 20% thất bại&quot;, thể hiện tính ngẫu nhiên của lịch sử</td></tr><tr><td>E31</td><td>Ghi chép chi tiết về phát hiện khảo cổ</td><td>Cài đặt phát hiện chi tiết và kết quả nghiên cứu của một cuộc khảo cổ liên mặt phẳng</td><td>Tài liệu 84-87</td><td>Có thể cài đặt như &quot;phát hiện khảo cổ của một nền văn minh bị mất&quot;, &quot;kết quả khảo cổ hồi quy thời gian của một nút lịch sử then chốt&quot;</td></tr></tbody></table><h2 id="_9-huong-mo-rong-lien-mat-phang-va-thoi-gian" tabindex="-1">9. Hướng Mở rộng Liên mặt phẳng và Thời gian <a class="header-anchor" href="#_9-huong-mo-rong-lien-mat-phang-va-thoi-gian" aria-label="Permalink to &quot;9. Hướng Mở rộng Liên mặt phẳng và Thời gian&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Số</th><th>Hướng Mở rộng</th><th>Giá trị Mở rộng</th><th>Cài đặt Liên quan</th><th>Đề xuất Sáng tạo</th></tr></thead><tbody><tr><td>E32</td><td>Cài đặt chi tiết của một mặt phẳng cụ thể</td><td>Cài đặt tham số quy luật, hình thái văn minh, môi trường địa lý và lịch sử của một mặt phẳng cụ thể</td><td>Tài liệu 80, Tài liệu 81</td><td>Có thể cài đặt các loại mặt phẳng cụ thể khác nhau như &quot;mặt phẳng ma thuật cao&quot;, &quot;mặt phẳng công nghệ&quot;, &quot;mặt phẳng hoang dã&quot;, &quot;mặt phẳng ý thức&quot;</td></tr><tr><td>E33</td><td>Các trường hợp ngoại giao liên mặt phẳng</td><td>Cài đặt các trường hợp cụ thể về việc văn minh cộng sinh và các văn minh mặt phẳng khác thiết lập quan hệ ngoại giao</td><td>Tài liệu 81, Tài liệu 88</td><td>Có thể cài đặt các sự kiện ngoại giao cụ thể như tiếp xúc đầu tiên, đàm phán thiết lập quan hệ, trao đổi văn hóa, hiệp định thương mại</td></tr><tr><td>E34</td><td>Các trường hợp cụ thể của hồi quy thời gian</td><td>Cài đặt quy trình cụ thể, phát hiện và tác động của một hoạt động hồi quy thời gian</td><td>Tài liệu 82-83, Tài liệu 89</td><td>Có thể cài đặt các trường hợp như &quot;giải mã hồi quy của một bí ẩn lịch sử&quot;, &quot;phục hồi hồi quy của một nền văn minh tuyệt chủng&quot;</td></tr><tr><td>E35</td><td>Ghi chép chi tiết về sự kiện nghịch lý thời gian</td><td>Cài đặt toàn bộ quá trình xảy ra, ứng phó khẩn cấp và sửa chữa nhân quả của một sự kiện nghịch lý thời gian</td><td>Tài liệu 89</td><td>Có thể viết ghi chép xử lý hoàn chỉnh của một sự kiện nghịch lý quy mô nhỏ, thể hiện vận hành thực tế của cơ chế phòng ngừa và kiểm soát</td></tr><tr><td>E36</td><td>Xung đột và giải quyết liên mặt phẳng</td><td>Cài đặt xung đột giữa văn minh cộng sinh và các văn minh mặt phẳng khác cũng như quy trình giải quyết hòa bình của chúng</td><td>Tài liệu 81, Tài liệu 88</td><td>Có thể cài đặt các loại trường hợp xung đột liên mặt phẳng khác nhau như tranh chấp tài nguyên, xung đột văn hóa, tranh chấp biên giới</td></tr></tbody></table><h2 id="_10-nguyen-tac-sang-tao-cho-cai-đat-mo-rong" tabindex="-1">10. Nguyên tắc Sáng tạo cho Cài đặt Mở rộng <a class="header-anchor" href="#_10-nguyen-tac-sang-tao-cho-cai-đat-mo-rong" aria-label="Permalink to &quot;10. Nguyên tắc Sáng tạo cho Cài đặt Mở rộng&quot;">​</a></h2><p>Khi thực hiện sáng tạo cài đặt mở rộng, cần tuân theo các nguyên tắc sau:</p><ol><li><strong>Ưu tiên tính nhất quán</strong>: Tất cả các cài đặt mở rộng phải duy trì tính nhất quán logic với cài đặt hiện có và vượt qua kiểm tra của bảng tự kiểm tra mâu thuẫn cài đặt.</li><li><strong>Dựa trên thực tế</strong>: Cài đặt mở rộng nên dựa trên quy luật khách quan để suy luận hợp lý, tránh tưởng thuần túy và sự sụp đổ của cài đặt.</li><li><strong>Lập trường cộng sinh</strong>: Cài đặt mở rộng phải luôn duy trì lập trường cốt lõi chống cướp bóc và ủng hộ cộng sinh, không được bênh vực hành vi cướp bóc.</li><li><strong>Sự cởi mở</strong>: Cài đặt mở rộng nên duy trì một mức độ cởi mở nhất định, dành chỗ cho việc mở rộng thêm trong tương lai.</li><li><strong>Tính thực tế</strong>: Cài đặt mở rộng nên có giá trị sáng tạo thực tế, có khả năng cung cấp vật liệu hữu ích cho sáng tạo câu chuyện, thiết kế trò chơi và thảo luận lý thuyết.</li></ol><h2 id="ket-luan" tabindex="-1">Kết luận <a class="header-anchor" href="#ket-luan" aria-label="Permalink to &quot;Kết luận&quot;">​</a></h2><p>Danh sách Đề xuất Mở rộng Cài đặt là &quot;cánh cửa mở&quot; của hệ thống cài đặt Văn minh Cộng sinh Mỏ neo. Nó chỉ ra rằng hệ thống cài đặt này không phải là một sản phẩm đóng cửa, hoàn chỉnh, mà là một hệ thống sống liên tục phát triển và liên tục phong phú. Ba mươi sáu hướng mở rộng chỉ là điểm khởi đầu; sức sáng tạo cài đặt thực sự đến từ trí tưởng tượng và nhiệt huyết của mỗi người tham gia. Miễn là tuân theo các nguyên tắc cơ bản của tính nhất quán cài đặt, mỗi mở rộng có giá trị sẽ trở thành một phần không thể thiếu trong câu chuyện hùng vĩ của Văn minh Cộng sinh Mỏ neo.</p><h2 id="tai-lieu-lien-quan" tabindex="-1">Tài liệu Liên quan <a class="header-anchor" href="#tai-lieu-lien-quan" aria-label="Permalink to &quot;Tài liệu Liên quan&quot;">​</a></h2><ul><li>97-Bảng Tự kiểm tra Mâu thuẫn Cài đặt</li><li>99-Phiên bản và Hướng dẫn Bảo trì Tài liệu</li><li>96-Câu hỏi Thường gặp FAQ</li></ul>',27)])])}const q=n(g,[["render",u]]);export{p as __pageData,q as default};
